import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final long M = 1000000007L;
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        int cnt;
        if (k == 0) {
            cnt = p - 1;
        } else if (k == 1) {
            cnt = p;
        } else {
            cnt = 0;
            boolean[] vis = new boolean[p];
            for (int i = 1; i < p; i++) {
                if (!vis[i]) {
                    vis[i] = true;
                    cnt++;
                    int j = (int)((long)i * k % p);
                    while (!vis[j]) {
                        vis[j] = true;
                        j = (int)((long)j * k % p);
                    }
                }
            }
        }
        long ans = 1;
        for (int j = 0; j < cnt; j++) {
            ans = (ans * p) % M;
        }
        System.out.println(ans);
        sc.close();
    }
}
